import {fork} from 'node:child_process';
import {mkdtempSync,mkdirSync,writeFileSync,realpathSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createIdentity,publicKeyText,signCommand} from '../../src/phone/protocol/e2e.ts';
import {createRelay} from '../../../relay/src/relay.ts';
export const until=async(fn,timeout=12000)=>{const end=Date.now()+timeout;while(Date.now()<end){const value=await fn();if(value)return value;await new Promise(r=>setTimeout(r,40));}throw Error('Full device fixture condition timed out');};
export async function createDeviceHarness(options={}){
 const root=realpathSync(mkdtempSync(join(tmpdir(),'full-device-fixture-')));process.env.HOME=root;process.env.DATABASE_PATH=join(root,'unused-parent.db');process.env.AGENT_PLAYER_CONFIG_DIR=join(root,'parent-config');process.env.NODE_ENV='test';mkdirSync(join(root,'anchors'));const authority=createIdentity(),relay=createRelay({port:0}),address=await relay.listen(),relayUrl=`ws://127.0.0.1:${address.port}/v1`;let generation=1,clock=0;const peers=[],links=new Map();
 const pairKey=(a,b)=>[a,b].sort().join(':');
 const snapshot=(id,changes={})=>signCommand(authority,id,++clock,JSON.stringify({version:1,workspace:'fixture_workspace',owner:{issuer:'https://identity.example.test',subject:'synthetic-subject'},generation,expiresAt:Date.now()+90000,devices:peers.map(p=>p.identity).map(p=>({id:p.id,publicKey:p.publicKey})),links:[...links.values()],...changes}));
 const request=(p,operation,args={})=>new Promise((resolve,reject)=>{const id=++p.next;const timer=setTimeout(()=>{p.pending.delete(id);reject(Error(`Fixture ${p.name} ${operation} timed out`));},20000);p.pending.set(id,{resolve:value=>{clearTimeout(timer);resolve(value);},reject:error=>{clearTimeout(timer);reject(Error(p.name+' '+operation+': '+error.message));}});p.child.send({id,operation,args});});
 for(let i=0;i<3;i++){
  const profile=join(root,'profile-'+i);mkdirSync(profile);const child=fork(fileURLToPath(new URL('./device-full-profile.mjs',import.meta.url)),[],{execPath:process.execPath,execArgv:['--import','tsx'],env:{...process.env,NODE_ENV:'test',DEVICE_FIXTURE_ROOT:root,DEVICE_PROFILE_ROOT:profile,...(options.pgUrls?{AGENT_PLAYER_DB:'postgres',AGENT_PLAYER_PG_URL:options.pgUrls[i]}:{AGENT_PLAYER_DB:'sqlite'})},stdio:['ignore','pipe','pipe','ipc']});
  const p={child,name:['First computer','Second computer','Third computer'][i],pending:new Map(),next:0,identity:null,stderr:'',stdout:'',request:(op,args)=>request(p,op,args)};child.stdout.on('data',b=>{p.stdout+=b;});child.stderr.on('data',b=>{p.stderr+=b;});
  child.on('message',async m=>{if(m.event==='authority'){try{if(m.operation==='revoke'){const key=pairKey(p.identity.id,m.args.peer),old=links.get(key);if(!old||old.epoch!==m.args.epoch)throw Error('Fixture epoch changed');links.set(key,{...old,epoch:old.epoch+1,revoked:true});}else if(m.operation==='recover'){for(const [key,old] of links)if(old.devices.some(id=>m.args.lost.includes(id)))links.set(key,{...old,epoch:old.epoch+1,revoked:true});}else throw Error('Unknown authority fixture operation');generation++;await Promise.all(peers.filter(other=>other!==p).map(other=>other.request('snapshot',{snapshot:snapshot(other.identity.id)})));child.send({parentResponse:m.id,result:snapshot(p.identity.id)});}catch(error){child.send({parentResponse:m.id,error:error.message});}return;}const pending=p.pending.get(m.id);p.pending.delete(m.id);if(m.error)pending?.reject(Error(p.name+': '+m.error));else pending?.resolve(m.result);});
  child.on('exit',(code,signal)=>{for(const pending of p.pending.values())pending.reject(Error(`Fixture exited ${code??signal}: ${p.stderr.slice(-2000)}`));p.pending.clear();});peers.push(p);p.identity=await p.request('identity');
 }
 for(let a=0;a<3;a++)for(let b=a+1;b<3;b++)links.set(pairKey(peers[a].identity.id,peers[b].identity.id),{devices:[peers[a].identity.id,peers[b].identity.id].sort(),epoch:1,revoked:false});
 for(const p of peers)if(!options.enrollment)await p.request('configure',{snapshot:snapshot(p.identity.id),authorityKey:publicKeyText(authority.publicKey),relayUrl,name:p.name});
 let timer=null,closed=false;
 const pair=async(a,b)=>{const invitation=await peers[a].request('invite'),join=await peers[b].request('join',{qr:invitation.qr,name:peers[b].name});const local=await until(async()=>{const status=await peers[a].request('pairing');return status.requests.find(r=>r.id===invitation.id&&r.checkCode);});const remote=await until(async()=>{const status=await peers[b].request('pairing');return status.joins.find(r=>r.id===join.id&&r.checkCode);});if(local.checkCode!==remote.checkCode)throw Error('Pairing code mismatch');await peers[a].request('allow',{id:invitation.id,code:local.checkCode,join:false});await peers[b].request('allow',{id:join.id,code:remote.checkCode,join:true});};
 const start=async()=>{for(const p of peers)await p.request('start');await pair(0,1);await pair(0,2);await pair(1,2);const urls=await Promise.all(peers.map(p=>p.request('listen')));for(let a=0;a<3;a++)for(let b=0;b<3;b++)if(a!==b)await peers[a].request('direct',{peer:peers[b].identity.id,url:urls[b]});let lastRefresh=Date.now();timer=setInterval(()=>{for(const p of peers)if(options.manualPresence!==false)void p.request('advertise').catch(()=>{});if(Date.now()-lastRefresh>10000){lastRefresh=Date.now();for(const p of peers)void p.request('snapshot',{snapshot:snapshot(p.identity.id)}).catch(()=>{});}},300);if(options.waitForDirect!==false)await until(async()=>{const views=await Promise.all(peers.map(p=>p.request('view')));return views.every(v=>v.devices.length===2&&v.devices.every(d=>d.path==='direct'));});return urls;};
 const enroll=async()=>{try{for(const p of peers)await p.request('enrollment-init',{relayUrl});const host=await peers[0].request('owner-code',{name:peers[0].name});for(let i=1;i<peers.length;i++){const joining=await peers[i].request('prepare-join',{text:host.hostInvitation,name:peers[i].name});await peers[0].request('enrollment-pin',{text:joining.deviceCode});const review=await peers[i].request('request-join'),pending=(await peers[0].request('enrollment-status')).pending.find(r=>r.checkCode===review.checkCode);if(!pending)throw Error('Concrete enrollment code mismatch');await peers[0].request('approve-enrollment',{peer:pending.deviceId,code:pending.checkCode});await peers[i].request('complete-join',{code:review.checkCode});}for(const p of peers){await p.request('bind-slot');await p.request('refresh-authority');const v=await p.request('view');p.identity={...p.identity,id:v.self.id};}return host;}catch(error){const diagnostics=await Promise.all(peers.map(p=>p.request('diagnostics').catch(e=>({error:e.message}))));throw Error(error.message+' | '+JSON.stringify(diagnostics));}};
 const approveTask=async(target,taskId)=>{const item=await until(async()=>{const v=await peers[target].request('view');return v.attempts.find(a=>a.taskId===taskId&&a.approvalId);});return peers[target].request('approve',{id:item.approvalId});};
 const approveRecord=async(target,id)=>{const record=await peers[target].request('sync-read',{id});if(record.approval_id)return peers[target].request('approve',{id:record.approval_id});const approvals=await peers[target].request('approvals');const approval=approvals.find(a=>a.toolName==='workspace_control_apply'&&a.paramsPreview?.operationId===record.operation_id);if(!approval)throw Error('Fixture approval unavailable');return peers[target].request('approve',{id:approval.id});};
 const close=async()=>{if(closed)return;closed=true;if(timer)clearInterval(timer);await Promise.all(peers.map(async p=>{try{await p.request('stop');}catch{}if(p.child.connected)p.child.disconnect();}));await relay.close();writeFileSync(join(root,'fixture-receipt.json'),JSON.stringify({profiles:peers.map(p=>({name:p.name,id:p.identity.id,stderr:p.stderr,stdout:p.stdout})),closed:true,actualModels:0,actualOriginalData:false},null,2));};
 return {root,peers,relayUrl,start,enroll,pair,approveTask,approveRecord,close,snapshot,authorityKey:publicKeyText(authority.publicKey)};
}
